export function materiById(id: string): MateriRingkas | undefined {
  const m = materiBank.find((mm) => mm.id === id);
  if (!m) return undefined;
  // 7 topik Fase A punya caraAjari inline; 41 sisanya diambil dari peta hasil workflow.
  const withCara = m.caraAjari ? m : { ...m, caraAjari: caraAjariExtra[id] };
  // Rumus kunci: 4 topik punya inline; 31 topik lain digabung dari rumusExtra (ekstraksi terverifikasi).
  if (withCara.rumus?.length || !rumusExtra[id]) return withCara;
  return { ...withCara, rumus: rumusExtra[id] };
}
